def write_back_history(apps, schema_editor):
    """Installations that ran before the log existed get their history from
    what the records already say: opened, scanned, each step's start and
    finish, delays, photos, going live and the handover. Who started a step
    before it was recorded is not known, so those lines carry no name."""
    Installation = apps.get_model("sites", "DeviceInstallation")
    Activity = apps.get_model("sites", "InstallationActivity")
    Step = apps.get_model("sites", "InstallationStep")
    Delay = apps.get_model("sites", "InstallationDelay")
    Photo = apps.get_model("sites", "InstallationPhoto")
    Handover = apps.get_model("sites", "HandoverRecord")
    Event = apps.get_model("assets", "DeviceLifecycleEvent")

    def who(u):
        return (f"{u.first_name} {u.last_name}".strip() or u.username) if u else ""

    rows = []

    def add(inst, at, action, text, actor=None, step=None):
        if at is not None:
            rows.append(Activity(installation=inst, step=step, action=action, text=text[:500], actor=actor, at=at))

    step_types = {"survey": "Survey", "wiring": "Wiring", "structure": "Metal Structure", "programming": "Programming",
                  "testing": "Testing & Commissioning", "handover": "Handover", "other": "Other"}
    causes = {"client": "Client", "internal": "Internal", "vendor": "Vendor", "other": "Other"}
    for inst in Installation.objects.select_related("site", "device", "installed_by", "asset_verified_by").iterator():
        if Activity.objects.filter(installation=inst).exists():
            continue
        add(inst, inst.created_at, "opened",
            f"Installation opened at {inst.site.name}"
            + (f", assigned to {who(inst.installed_by)}" if inst.installed_by_id else "")
            + (f", due {inst.due_date:%d %b %Y}" if inst.due_date else ""))
        if inst.asset_verified_at:
            add(inst, inst.asset_verified_at, "asset_scanned", f"Asset {inst.device.asset_code} scanned on site",
                actor=inst.asset_verified_by)
        for st in Step.objects.filter(installation=inst).select_related("completed_by", "started_by"):
            label = st.custom_label or step_types.get(st.step_type, st.step_type)
            if st.step_type == "handover":
                continue
            if st.started_at and st.status != "not_started":
                add(inst, st.started_at, "step_in_progress", f"{label} started", actor=st.started_by, step=st)
            if st.completed_at and st.status == "completed":
                add(inst, st.completed_at, "step_completed", f"{label} completed", actor=st.completed_by, step=st)
            if st.status == "skipped":
                add(inst, st.updated_at, "step_skipped", f"{label} skipped", step=st)
        for d in Delay.objects.filter(installation=inst).select_related("reported_by"):
            add(inst, d.created_at, "delay",
                f"Delay flagged: {causes.get(d.cause, d.cause)}" + (f" - {d.description}" if d.description else ""),
                actor=d.reported_by, step=d.step if d.step_id else None)
            if d.resolved_at:
                add(inst, d.resolved_at, "delay_resolved", f"Delay resolved: {causes.get(d.cause, d.cause)}")
        for ph in Photo.objects.filter(installation=inst).select_related("taken_by"):
            add(inst, ph.created_at, "photo", f"{ph.get_photo_type_display()} photo added", actor=ph.taken_by)
        live = (Event.objects.filter(device=inst.device, event_type="status_change", to_value="active",
                                     created_at__gte=inst.created_at)
                .select_related("performed_by").order_by("created_at").first())
        if live is not None:
            add(inst, live.created_at, "activated", f"{inst.device.asset_code} marked Active", actor=live.performed_by)
        hand = Handover.objects.filter(installation=inst).select_related("performed_by").first()
        if hand is not None:
            add(inst, hand.created_at, "handed_over", f"Handover recorded - accepted by {hand.accepted_by_name}",
                actor=hand.performed_by)
        if len(rows) > 500:
            Activity.objects.bulk_create(rows)
            rows.clear()
    Activity.objects.bulk_create(rows)



